create or replace function public.business_location_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,auth,extensions,pg_temp as $$ select jsonb_build_object('business_id',p_business_id,'locations',count(*),'active_locations',count(*) filter(where l.is_active)) from public.locations l where l.business_id=p_business_id and public.is_platform_owner(auth.uid()); $$;
create or replace function public.business_location_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,auth,extensions,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.check_ins desc,x.name),'[]'::jsonb) from (select l.id,l.name,l.address,l.city,l.state,l.is_active,l.rating,l.review_count,count(distinct ci.id) filter(where ci.checked_in_at between p_start and p_end) check_ins,count(distinct ci.user_id) filter(where ci.checked_in_at between p_start and p_end) unique_visitors,count(distinct r.id) filter(where r.created_at between p_start and p_end and r.status<>'hidden') reviews from public.locations l left join public.check_ins ci on ci.location_id=l.id left join public.reviews r on r.location_id=l.id where l.business_id=p_business_id group by l.id) x where public.is_platform_owner(auth.uid()); $$;
